# One run of an ExperiencePrompt, generated by its own job or uploaded by an admin.
class ExperienceImage < ApplicationRecord
  belongs_to :experience_prompt, touch: true

  has_one_attached :file do |attachable|
    attachable.variant :display, resize_to_limit: [ 600, 800 ], format: :webp, preprocessed: true
  end

  enum :status, { pending: "pending", queued: "queued", generating: "generating", succeeded: "succeeded", failed: "failed" },
       default: :pending
  # Uploaded images were made outside the app, so later wording edits never mark them outdated.
  enum :source, { generated: "generated", uploaded: "uploaded" }, default: :generated

  def current?
    succeeded? && (uploaded? || prompt == experience_prompt.prompt)
  end

  def outdated?
    succeeded? && !current?
  end

  def generate!(client: ImageGeneration::OpenaiClient.new)
    return if current?

    update!(status: :generating, attempts: attempts + 1, error: nil)
    result = client.generate(prompt: experience_prompt.prompt)
    file.attach(io: StringIO.new(result.bytes), filename: format("%02d.%s", position, result.format),
                content_type: "image/#{result.format}")
    update!(status: :succeeded, source: :generated, prompt: experience_prompt.prompt, model: result.model,
            generated_at: Time.current)
  rescue ImageGeneration::Transient
    update!(status: :queued)
    raise
  rescue ImageGeneration::Error => error
    fail!(error.message)
  end

  def display_path
    return unless file.attached?

    # Same-origin proxy, not the S3 redirect, so the exhibition's service worker can cache the image itself.
    Rails.application.routes.url_helpers.rails_storage_proxy_path(file.variant(:display), only_path: true)
  end

  def fail!(message)
    update!(status: :failed, error: message.to_s.truncate(2_000))
  end

  def regenerate!
    clear!
    update!(status: :queued)
    GenerateExperienceImageJob.perform_later(self)
  end

  def clear!
    file.purge if file.attached?
    update!(status: :pending, source: :generated, error: nil, generated_at: nil, model: nil)
  end

  def upload!(file_param)
    file.attach(file_param)
    update!(status: :succeeded, source: :uploaded, prompt: experience_prompt.prompt, model: nil, error: nil,
            generated_at: Time.current)
  end
end
